import { TextureAnimationTexture } from "./TextureAnimationTexture";
export class CompiledTexture {
    id;
    static GetAtlasIndex = (x, y, boundsX) => x + y * boundsX;
    static GetAtlasPosition = (index, boundsX, position = [0, 0]) => {
        position[1] = Math.floor(index / boundsX);
        position[0] = Math.floor(index % boundsX);
        return position;
    };
    images = [];
    /**Maps texture ids to their atlas sizes  */
    atlasSizeMap = {};
    /**Maps texture ids to their index */
    textureMap = {};
    animations = [];
    /**To be used by the renderer to store a refernce to the actual texture used for rendering */
    shaderTexture;
    animatedTexture;
    constructor(id) {
        this.id = id;
        this.animatedTexture = new TextureAnimationTexture(this);
    }
    getTextureIndex(id) {
        if (typeof id == "number") {
            return id;
        }
        let finalId = "";
        let frameIndex = 0;
        if (!Array.isArray(id)) {
            finalId = id;
        }
        if (Array.isArray(id)) {
            finalId = id[0];
            if (typeof id[1] == "number")
                frameIndex = id[1];
            if (Array.isArray(id[1]))
                frameIndex = CompiledTexture.GetAtlasIndex(id[1][0], id[1][1], this.atlasSizeMap[finalId][0]);
            if (typeof id[1] == "string") {
                finalId = `${id[0]}:${id[1]}`;
                if (typeof id[2] == "number")
                    frameIndex = id[2];
                if (Array.isArray(id[2]))
                    frameIndex = CompiledTexture.GetAtlasIndex(id[2][0], id[2][1], this.atlasSizeMap[finalId][0]);
            }
        }
        const index = this.textureMap[finalId];
        if (index === undefined) {
            console.warn(`Texture with id [passed in: ${id.toString()}] [final: ${finalId}] does not exist on compiled texture [${this.id}]`, this.textureMap);
            return 0;
        }
        return index + frameIndex;
    }
    getTexturePath(id) {
        return this.images[this.getTextureIndex(id)].src;
    }
    canvas;
    context;
    setUpCanvas() {
        if (this.canvas)
            return;
        this.canvas = document.createElement("canvas");
        this.context = this.canvas.getContext("2d", {
            willReadFrequently: true,
        });
    }
    async getTextureData(id) {
        this.setUpCanvas();
        const path = this.images[this.getTextureIndex(id)].src;
        const res = await fetch(path);
        if (!res.ok)
            throw new Error(`Failed to fetch texture: ${path}`);
        const blob = await res.blob();
        const bitmap = await createImageBitmap(blob);
        this.canvas.width = bitmap.width;
        this.canvas.height = bitmap.height;
        this.context.translate(0, bitmap.height);
        this.context.scale(1, -1);
        this.context.drawImage(bitmap, 0, 0);
        return this.context.getImageData(0, 0, bitmap.width, bitmap.height).data;
    }
    getTextureDataSync(id) {
        this.setUpCanvas();
        const img = this.images[this.getTextureIndex(id)];
        if (!img) {
            throw new Error(`Texture image not found for ID: ${id}`);
        }
        if (!img.complete || img.naturalWidth === 0) {
            throw new Error(`Texture image is not fully loaded yet: ${img.src}`);
        }
        const width = img.naturalWidth;
        const height = img.naturalHeight;
        this.canvas.width = width;
        this.canvas.height = height;
        this.context.translate(0, height);
        this.context.scale(1, -1);
        this.context.drawImage(img, 0, 0);
        return this.context.getImageData(0, 0, width, height).data;
    }
}
